"use client";

import React, { useState } from "react";
import { Check, Copy, ChevronDown, ChevronRight, Brain } from "lucide-react";

interface MarkdownRendererProps {
  content: string;
}

export function MarkdownRenderer({ content }: MarkdownRendererProps) {
  // 1. Separate <think> or <thought> reasoning tokens if generated by deep reasoning models
  let thinkingContent: string | null = null;
  let mainContent = content;

  const thinkMatch = content.match(/<(?:think|thought)>([\s\S]*?)<\/(?:think|thought)>/i);
  if (thinkMatch) {
    thinkingContent = thinkMatch[1].trim();
    mainContent = content.replace(/<(?:think|thought)>[\s\S]*?<\/(?:think|thought)>/gi, "").trim();
  }

  const [showThinking, setShowThinking] = useState(false);

  return (
    <div className="space-y-3 leading-relaxed text-[var(--text-main)]">
      {/* Collapsible Thinking Process block (like ChatGPT / DeepSeek) */}
      {thinkingContent && (
        <div className="rounded-xl border border-[var(--border-subtle)] bg-[var(--bg-main)]/70 overflow-hidden text-xs my-2">
          <button
            onClick={() => setShowThinking(!showThinking)}
            className="w-full flex items-center justify-between px-3.5 py-2 text-[var(--text-muted)] hover:text-[var(--text-main)] hover:bg-[var(--bg-card)]/50 transition-colors font-medium text-[11px]"
          >
            <div className="flex items-center gap-2">
              <Brain className="w-3.5 h-3.5 text-[#6366F1]" />
              <span>Thought Process</span>
            </div>
            {showThinking ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
          </button>
          {showThinking && (
            <div className="p-3.5 pt-1 text-[var(--text-muted)] border-t border-[var(--border-subtle)]/60 whitespace-pre-wrap font-mono text-[11px] leading-relaxed">
              {thinkingContent}
            </div>
          )}
        </div>
      )}

      {/* Main Plain Text / Markdown Response */}
      <FormattedText content={mainContent} />
    </div>
  );
}

function FormattedText({ content }: { content: string }) {
  if (!content) return null;

  // Split by code blocks: ```lang ... ```
  const parts = content.split(/(```[\s\S]*?```)/g);

  return (
    <div className="space-y-3">
      {parts.map((part, index) => {
        if (part.startsWith("```") && part.endsWith("```")) {
          // Extract language and code
          const firstLineEnd = part.indexOf("\n");
          const lang = firstLineEnd > 0 ? part.slice(3, firstLineEnd).trim() || "code" : "code";
          const code = firstLineEnd > 0 ? part.slice(firstLineEnd + 1, -3).trim() : part.slice(3, -3).trim();

          return <CodeBlock key={index} lang={lang} code={code} />;
        }

        // Render natural plain text with preserved whitespace and line breaks (like ChatGPT)
        return <TextBlock key={index} text={part} />;
      })}
    </div>
  );
}

function CodeBlock({ lang, code }: { lang: string; code: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="rounded-xl overflow-hidden border border-[var(--border-subtle)] bg-[var(--bg-main)] my-2 text-xs font-mono shadow-sm">
      <div className="flex items-center justify-between px-3.5 py-1.5 bg-[var(--bg-card)] border-b border-[var(--border-subtle)] text-[var(--text-muted)]">
        <span className="text-[11px] font-semibold text-[var(--text-main)] uppercase">{lang}</span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1.5 px-2 py-0.5 rounded text-[11px] hover:text-[var(--text-main)] hover:bg-[var(--bg-main)] transition-colors"
        >
          {copied ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
          <span>{copied ? "Copied" : "Copy"}</span>
        </button>
      </div>
      <div className="p-3.5 overflow-x-auto text-[var(--text-main)]">
        <pre>{code}</pre>
      </div>
    </div>
  );
}

function TextBlock({ text }: { text: string }) {
  // Plain text rendering with preserved paragraphs and natural formatting like ChatGPT
  return (
    <div className="whitespace-pre-wrap leading-relaxed text-[var(--text-main)]">
      {renderInlineStyles(text)}
    </div>
  );
}

// Formats **bold**, *italic*, and `code` inline while preserving plain text
function renderInlineStyles(text: string): React.ReactNode {
  const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*)/g);

  return parts.map((part, i) => {
    if (part.startsWith("`") && part.endsWith("`")) {
      return (
        <code
          key={i}
          className="px-1.5 py-0.5 rounded bg-[var(--bg-main)] border border-[var(--border-subtle)] font-mono text-[11px] text-[#6366F1]"
        >
          {part.slice(1, -1)}
        </code>
      );
    }
    if (part.startsWith("**") && part.endsWith("**")) {
      return (
        <strong key={i} className="font-semibold text-[var(--text-main)]">
          {part.slice(2, -2)}
        </strong>
      );
    }
    if (part.startsWith("*") && part.endsWith("*")) {
      return (
        <em key={i} className="italic text-[var(--text-main)] opacity-95">
          {part.slice(1, -1)}
        </em>
      );
    }
    return part;
  });
}
